28	template <int Arch, int kHeadDim, int kHeadDimV, int ClusterM, typename Element, typename ElementOut,
29	          bool Is_causal, bool Is_local, bool Has_softcap, bool Varlen, bool PagedKVNonTMA, bool AppendKV, bool HasQv,
30	          bool PackGQA, bool Split, bool V_colmajor, bool Use_one_mma_wg, int kBlockH=1>
31	void run_flash_fwd(Flash_fwd_params &params, cudaStream_t stream) {
32	    static_assert(!(Is_causal && Is_local), "Causal and Local cannot be enabled at the same time");
33	    static_assert(!(AppendKV && V_colmajor), "AppendKV and V_colmajor cannot be enabled at the same time");
34	    static_assert(!(AppendKV && !Varlen), "AppendKV requires Varlen");
35	    static constexpr bool Is_FP8 = cute::is_same_v<Element, cutlass::float_e4m3_t> || cute::is_same_v<Element, cutlass::float_e5m2_t>;
36	    static constexpr bool FP8_TransposeV = Is_FP8 && !V_colmajor;
37	    using ArchTag = std::conditional_t<Arch >= 90, cutlass::arch::Sm90, cutlass::arch::Sm80>;
38	    using ElementS = cutlass::bfloat16_t;
39	
