                 TileShape_MNK_PV, GMMA::Major::K, MmaMajorV>()),
        decltype(cute::GMMA::rs_op_selector<Element, Element, ElementAccum,
                 TileShape_MNK_PV, GMMA::Major::K, MmaMajorV>())
    >{},
